# ==============================================================================# 095_WORKFLOW_ENGINE.py## IOTEC WORKFLOW ENGINE## Missão:# Orquestrar automaticamente os fluxos comerciais.## ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class WorkflowEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS workflow_events(            id INTEGER PRIMARY KEY AUTOINCREMENT,            workflow_uuid TEXT UNIQUE,            opportunity_uuid TEXT,            trigger_event TEXT,            action_name TEXT,            execution_order INTEGER,            status TEXT,            executed_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # -----------------------------------------------------------------    def _sha(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # -----------------------------------------------------------------    def create_default_workflow(self, opportunity_uuid):        actions=[            (1,"Enviar apresentação institucional"),            (2,"Enviar e-mail inicial"),            (3,"Agendar retorno"),            (4,"Registrar follow-up"),            (5,"Avaliar avanço do pipeline")        ]        total=0        for ordem,acao in actions:            payload={                "workflow_uuid":str(uuid.uuid4()),                "opportunity_uuid":opportunity_uuid,                "trigger_event":"FIRST_CONTACT",                "action_name":acao,                "execution_order":ordem,                "status":"PENDING",                "executed_at":None,                "metadata":{                    "origin":"095_WORKFLOW_ENGINE"                }            }            assinatura=self._sha(payload)            self.conn.execute("""            INSERT INTO workflow_events(                workflow_uuid,                opportunity_uuid,                trigger_event,                action_name,                execution_order,                status,                executed_at,                metadata,                hash            )            VALUES(?,?,?,?,?,?,?,?,?)            """,(                payload["workflow_uuid"],                payload["opportunity_uuid"],                payload["trigger_event"],                payload["action_name"],                payload["execution_order"],                payload["status"],                payload["executed_at"],                json.dumps(payload["metadata"],ensure_ascii=False),                assinatura            ))            total+=1        self.conn.commit()        return total# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    conn=sqlite3.connect(DB)    conn.row_factory=sqlite3.Row    oportunidade=conn.execute("""        SELECT opportunity_uuid        FROM commercial_pipeline        LIMIT 1    """).fetchone()    if oportunidade is None:        raise RuntimeError("Nenhuma oportunidade encontrada.")    engine=WorkflowEngine()    total=engine.create_default_workflow(        oportunidade["opportunity_uuid"]    )    print("="*80)    print("WORKFLOW ENGINE")    print("="*80)    print(f"Ações criadas : {total}")    print("Status        : SUCCESS")    print("="*80)